this.swarm.join(this.config.channel, { server: true, client: true });
// intercom-dex patch (bounded-replicate-flush): flush() waits until every node found on the subnet topic was
// tried, three at a time (about 190 RESET nodes: 9 minutes). Replication needs only the first connections:
// continue 10 s after the first one, or after 60 s at most; the swarm keeps connecting in the background.
await new Promise((resolve) => {
    let done = false, first = null;
    const finish = () => { if (done) return; done = true; clearTimeout(cap); clearTimeout(first); this.swarm.off('connection', onConnection); resolve(); };
    const onConnection = () => { if (first === null) first = setTimeout(finish, 10000); };
    const cap = setTimeout(finish, 60000);
    if (this.swarm.connections.size > 0) onConnection();
    this.swarm.on('connection', onConnection);
    this.swarm.flush().then(finish, finish);
});
